<?php
require_once dirname(__DIR__).'/includes/auth.php';$u=require_role('coordinator');$err='';$department=(int)$u['department_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$id=(int)($_POST['check_id']??0);$decision=(string)($_POST['reviewer_decision']??'');$note=post_string('reviewer_note',1000);
 if(!in_array($decision,['distinct','potential_duplicate','needs_discussion'],true))$err='Select a valid reviewer decision.';
 else{$q=db()->prepare('SELECT c.id FROM project_similarity_checks c JOIN projects p ON p.id=c.project_id WHERE c.id=? AND p.department_id=?');$q->execute([$id,$department]);if(!$q->fetchColumn())$err='This similarity record is outside your department.';else{db()->prepare('UPDATE project_similarity_checks SET reviewer_decision=?,reviewer_note=? WHERE id=?')->execute([$decision,$note?:null,$id]);audit('similarity_reviewed','similarity_check',$id,'HOD similarity decision: '.$decision);flash('success','Similarity review saved.');redirect('coordinator/similarity.php');}}
}
$q=db()->prepare('SELECT c.*,p.title project_title,p.reference_no project_ref,other.title compared_title,other.reference_no compared_ref,u.first_name,u.last_name FROM project_similarity_checks c JOIN projects p ON p.id=c.project_id JOIN projects other ON other.id=c.compared_project_id JOIN users u ON u.id=c.checked_by WHERE p.department_id=? ORDER BY c.checked_at DESC LIMIT 500');$q->execute([$department]);$rows=$q->fetchAll();$pageTitle='Similarity Review';$crumbTrail=['Similarity'];require dirname(__DIR__).'/includes/header.php';
?>
<?php if($err): ?><div role="alert" class="alert alert-danger"><?= e($err) ?></div><?php endif; ?>
<?php $high=count(array_filter($rows,fn($r)=>(float)$r['similarity_score']>=60));$reviewed=count(array_filter($rows,fn($r)=>!empty($r['reviewer_decision']))); ?>
<div class="row g-3 mb-3"><div class="col-md-4"><div class="stat-card"><div class="stat-label">Comparison records</div><div class="stat-value"><?= count($rows) ?></div><small class="stat-sub">In your department</small></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">High similarity (60%+)</div><div class="stat-value text-red"><?= (int)$high ?></div><small class="stat-sub">Advisory only</small></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Assessed</div><div class="stat-value text-green"><?= (int)$reviewed ?></div><small class="stat-sub">Reviewer decision saved</small></div></div></div>
<p class="page-intro">Review possible title and description matches in your department. Scores are advisory and never reject an idea; this record helps the supervisor make an informed academic decision.</p>
<section class="card filter-bar mb-3"><div class="filter-form"><label class="search-box"><?= ui_icon('search') ?><input type="search" class="form-control" placeholder="Search records..." aria-label="Search similarity records" data-live-filter="#similarityTable tbody tr"></label></div></section>
<section class="card p-4"><h2 class="section-heading">Department Similarity Review</h2><div class="table-responsive"><table class="table table-soft align-middle" id="similarityTable"><thead><tr><th>Project</th><th>Compared with</th><th>Score</th><th>Checked</th><th>Similarity assessment</th></tr></thead><tbody>
<?php foreach($rows as $r): $sc=(float)$r['similarity_score']; ?><tr><td><strong><?= e($r['project_ref']) ?></strong><br><small class="text-muted"><?= e($r['project_title']) ?></small></td><td><strong><?= e($r['compared_ref']) ?></strong><br><small class="text-muted"><?= e($r['compared_title']) ?></small></td><td><span class="ui-pill <?= $sc>=60?'is-bad':($sc>=35?'is-warn':'is-ok') ?>"><?= e((string)$r['similarity_score']) ?>%</span><br><small class="text-muted"><?= e($r['algorithm_version']) ?></small></td><td class="text-muted text-nowrap"><?= e(ui_date($r['checked_at'])) ?></td><td>
<form method="post" class="assess-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="check_id" value="<?= (int)$r['id'] ?>"><select class="form-select form-select-sm" name="reviewer_decision" aria-label="Decision"><option value="distinct">No close match</option><option value="potential_duplicate" <?= $r['reviewer_decision']==='potential_duplicate'?'selected':'' ?>>Potential match</option><option value="needs_discussion" <?= $r['reviewer_decision']==='needs_discussion'?'selected':'' ?>>Needs discussion</option></select><input class="form-control form-control-sm" name="reviewer_note" value="<?= e($r['reviewer_note']??'') ?>" placeholder="Note" aria-label="Note"><button class="btn btn-sm btn-primary">Save assessment</button></form></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="5"><div class="empty-state">No similarity checks have been recorded. Run a similarity check from project monitoring to add comparison records.</div></td></tr><?php endif; ?></tbody></table></div></section>
